async function saveSettings(event) { event.preventDefault(); if (profile?.role !== 'doctor') return showToast('إعدادات العيادة للدكتورة فقط.'); const form = new FormData(event.currentTarget); const closed_weekdays = Array.from(event.currentTarget.closed_weekdays.selectedOptions).map(option => Number(option.value)); const closed_dates = String(form.get('closed_dates')).split(/\s+/).filter(Boolean); const service_prices = {}; ['first','follow','consult','aesthetic','birth','labs'].forEach(type => service_prices[type] = Math.max(0, Number(form.get(`price_${type}`) || 0))); const finance_enabled = form.get('finance_enabled') === 'on'; const { error } = await supabase.from('clinic_settings').update({ clinic_name:form.get('clinic_name'), max_daily_slots:Number(form.get('max_daily_slots')), work_start:form.get('work_start'), work_end:form.get('work_end'), closed_weekdays, closed_dates, service_prices, finance_enabled }).eq('id', true); if (error) return showToast(`تعذر حفظ الإعدادات: ${error.message}`); await loadData(); if (!financeEnabled() && activeView === 'finance') activeView = 'settings'; renderApp(); showToast(finance_enabled ? 'تم حفظ إعدادات العيادة في قاعدة البيانات.' : 'تم حفظ الإعدادات وإيقاف الحسابات.'); }
